export const copyReadsRegion = machine({
  description:
    "Note the closing in state x in one region, and the copy k of map m saves the notes into seen in the other region",
  context: { notes: z.array(z.string()).default([]), seen: z.array(z.string()).default([]) },
  receives: { tasksClosed },
  initial: "open",
  states: {
    open: {
      type: "parallel",
      states: {
        left: {
          initial: "m",
          states: { m: { type: "map", key: { name: z.string() }, initial: "c1", states: { c1: {} } } },
        },
        right: { initial: "x", states: { x: {}, y: {} } },
      },
    },
  },
}).chart({
  states: {
    m: { items: () => [{ name: "k" }] },
    c1: { on: { tasksClosed: [{ assign: { seen: ({ context }) => [...context.notes] } }] } },
    x: { on: { tasksClosed: [{ target: "y", assign: { notes: ({ context }) => [...context.notes, "x"] } }] } },
    y: { on: { tasksClosed: [{ target: "x" }] } },
  },
});

export const tracker = machine({
  description: "Mark that a task was added, once in each region",
  context: { status: z.enum(["empty", "added"]).default("empty") },
  receives: { taskAdded, tasksCleared },
  initial: "tracking",
  states: {
    tracking: {
      type: "parallel",
      states: {
        counting: { initial: "countIdle", states: { countIdle: {}, countMarking: {}, counted: {} } },
        remembering: { initial: "rememberIdle", states: { rememberIdle: {}, rememberMarking: {}, remembered: {} } },
      },
    },
  },
}).chart({
  on: { tasksCleared: [{ target: "tracking" }] },
  states: {
    countIdle: { on: { taskAdded: [{ target: "countMarking" }] } },
    countMarking: { always: [{ target: "counted", assign: { status: () => "added" } }] },
    rememberIdle: { on: { taskAdded: [{ target: "rememberMarking" }] } },
    rememberMarking: { always: [{ target: "remembered", assign: { status: () => "added" } }] },
  },
});

export const firstTask = query({
  output: { id: z.string().endsWith("1") },
}).resolve(({ records }) => {
  let first: string | undefined;
  records.Task.map((t) => (first ??= t.id));
  return { id: first ?? "" };
});

export const titlesInArray = query({
  output: { titles: z.array(z.string()) },
}).resolve(({ records }) => {
  const titles: string[] = [];
  records.Task.map((t) => titles.push(t.title));
  return { titles };
});

export const m = machine({
  description: "e1 enters waiting, whose at reads due; e2 moves due",
  context: { due: instant.nullable().default(null) },
  receives: { e1, e2 },
  commands: { ping },
  initial: "idle",
  states: { idle: {}, waiting: {}, pinging: {}, done: {} },
}).chart({
  on: { e2: [{ assign: { due: () => parseInstant("2026-10-25T06:00:00Z") } }] },
  states: {
    idle: { on: { e1: [{ target: "waiting" }] } },
    waiting: {
      after: {
        due: {
          at: ({ context }) => context.due ?? parseInstant("2026-10-25T05:00:00Z"),
          onFired: [{ target: "pinging" }],
        },
      },
    },
    pinging: { sends: { ping: { input: () => ({}), onAccepted: [{ target: "done" }] } } },
  },
});

export const alarm = machine({
  description: "Ring at an instant half a millisecond past 10:00, which the run's time cannot hold",
  initial: "waiting",
  states: { waiting: {}, ringing: { type: "final" } },
}).chart({
  states: {
    waiting: {
      after: {
        ring: {
          at: () => parseInstant("2026-10-25T01:00:00Z") + 0.5,
          onFired: [{ target: "ringing" }],
        },
      },
    },
  },
});

export const picker = machine({
  description: "Pick tags when the service starts",
  context: { picked: set(z.string()).default([]) },
  initial: "picking",
  states: { picking: {} },
}).chart({ states: { picking: { entry: { assign: { picked: () => ["a", "a"] } } } } });

export const tagCounter = machine({
  description: "Count the visits of each tag, and set the count below the minimum when a copy starts",
  initial: "counting",
  states: {
    counting: {
      type: "map",
      key: { tag: z.string() },
      context: { visits: z.number().min(1).default(1) },
      initial: "idle",
      states: { idle: {} },
    },
  },
}).chart({
  states: { counting: { items: () => [{ tag: "home" }] }, idle: { entry: { assign: { visits: () => 0 } } } },
});

export const Note = entity({
  description: "A note, or a reply to the note replyTo names",
  fields: { id: z.string(), replyTo: ref.self().nullable() },
  key: "id",
});

export const Pin = singleEntity({
  description: "The pinned task",
  fields: { taskId: ref(Task).nullable().default(null) },
});

export const reminder = machine({
  description:
    "Remind the largest safe integer of milliseconds after it starts, past every safe integer, which the run's time cannot hold",
  initial: "waiting",
  states: { waiting: {}, reminding: { type: "final" } },
}).chart({
  states: {
    waiting: { after: { far: { delay: 9_007_199_254_740_991, onFired: [{ target: "reminding" }] } } },
  },
});

export const tagWatcher = machine({
  description: "Watch each tag of the tasks",
  initial: "watching",
  states: { watching: { type: "map", key: { tag: Task.fields.tag }, initial: "idle", states: { idle: {} } } },
}).chart({
  states: { watching: { items: ({ records }) => records.Task.map((t) => ({ tag: t.tag })) } },
});

export const addTask = command({
  input: { taskId: Task.fields.id },
  emits: [taskAdded],
}).decide(({ input }) => [emit(taskAdded, { id: input.taskId, title: "" })]);

export const flow = machine({
  description: "Alternate through always transitions while no task exists",
  receives: { taskAdded },
  initial: "a",
  states: { a: {}, b: {} },
}).chart({
  states: {
    a: { always: [{ guard: { open: ({ records }) => records.Task.size === 0 }, target: "b" }] },
    b: { always: [{ guard: { open: ({ records }) => records.Task.size === 0 }, target: "a" }] },
  },
});

export const counter = machine({
  description: "Count on every count, going back and forth between two states",
  receives: { counted },
  commands: { count },
  initial: "ping",
  states: { ping: {}, pong: {} },
}).chart({
  states: {
    ping: { on: { counted: [{ target: "pong" }] }, sends: { count: { onAccepted: [], onRejected: [] } } },
    pong: { on: { counted: [{ target: "ping" }] }, sends: { count: { onAccepted: [], onRejected: [] } } },
  },
});

export const dayLater = scenario({
  description:
    "Start the service and come back a day later; more than 1000 minutes have passed, so test reports exceededDueDeadlines",
  given: { start: parseInstant("2026-10-25T09:00:00+09:00"), records: {}, peers: [] },
  when: (w) => {
    w.clock.at(parseInstant("2026-10-26T09:00:00+09:00"));
  },
  then: () => [],
});

export const pinger = machine({
  description: "Run 11 chains of 100 pings at the start, each ping sent when the one before is accepted",
  commands: { ping },
  initial: "chains",
  states: {
    chains: {
      type: "map",
      key: { chain: z.number() },
      context: { pings: z.number().default(1) },
      initial: "pinging",
      states: { pinging: {} },
    },
  },
}).chart({
  states: {
    chains: { items: () => Array.from({ length: 11 }, (_, chain) => ({ chain })) },
    pinging: {
      sends: {
        ping: {
          onAccepted: [
            {
              guard: { hasMore: ({ context }) => context.pings < 100 },
              target: "pinging",
              reenter: true,
              assign: { pings: ({ context }) => context.pings + 1 },
            },
          ],
        },
      },
    },
  },
});

export const start = scenario({
  description:
    "Start the home screen; it opens the done screen again each time the done screen is done, without end, so the start message runs more than 10000 work items and test reports exceededMessageWork",
  given: { start: parseInstant("2026-10-25T09:00:00+09:00"), records: {}, peers: [] },
  when: (w) => {
    w.startup.screen(homeScreen);
  },
  then: () => [],
});

export const rounds = machine({
  description: "Start a round again as soon as it is done",
  initial: "round",
  states: { round: { initial: "finished", states: { finished: { type: "final" } } } },
}).chart({
  states: { round: { onDone: [{ target: "round", reenter: true }] } },
});

export const logTitle = command({ input: { title: z.string(), from: date }, emits: [titleLogged] }).decide(
  ({ input }) => [emit(titleLogged, { title: input.title, until: addDays(input.from, 3_000_000) })],
);

export const counter = machine({
  description: "Count added tasks up to one",
  context: { count: z.number().default(0) },
  receives: { taskAdded },
  initial: "counting",
  states: { counting: {} },
  invariants: { atMostOne: ({ context }) => context.count <= 1 },
}).chart({ states: { counting: { on: { taskAdded: [{ assign: { count: ({ context }) => context.count + 1 } }] } } } });

export const addTask = command({
  input: { taskId: Task.fields.id, title: Task.fields.title },
  emits: [taskAdded],
  ensures: { keepsTitle: ({ input, records }) => records.Task.get(input.taskId)?.title === input.title },
}).decide(({ input }) => [emit(taskAdded, { id: input.taskId, title: input.title.toUpperCase() })]);

export const Task = entity({
  description: "A task",
  fields: { id: z.string(), title: z.string() },
  key: "id",
  invariants: { titleNotBlank: ({ record }) => record.title.trim() !== "" },
});

export const homeScreen = screen({
  description: "Open the picker",
  screens: { pickScreen },
  initial: "picking",
  states: { picking: {}, done: { type: "final" } },
}).chart({
  states: {
    picking: { opens: { pickScreen: { modal: true, input: () => ({ count: 0 }), onDone: [{ target: "done" }] } } },
  },
});

export const { command, createEvent, updateEvent, contract, scenario } = service({
  name: "invariantsBreakingTodo",
  description: "Keep the tasks while breaking the invariants of Task, Tally, and the service",
  entities: { Task, Tally },
  invariants: {
    uniqueTitles: ({ records }) =>
      records.Task.every((t) => records.Task.filter((u) => u.title === t.title).size === 1),
  },
});

export const Tally = singleEntity({
  description: "The number of added tasks",
  fields: { added: z.number().default(0) },
  invariants: { belowTwo: ({ record }) => record.added < 2 },
});

export const watcher = machine({
  description: "Watch the first task",
  receives: { taskAdded },
  initial: "running",
  states: {
    running: { initial: "watching", states: { idle: {}, watching: { held: { task: z.object(Task.fields) } } } },
  },
}).chart({
  states: {
    running: { initial: { with: { task: ({ records }) => records.Task.only() } } },
    watching: { on: { taskAdded: [{ target: "idle" }] } },
  },
});

export const limits = machine({
  description: "Hold the limit",
  context: { limit: z.number().min(1).default(0) },
  initial: "holding",
  states: { holding: {} },
}).chart({});

export const notifier = machine({
  description: "Mail the user, whose address is not known yet",
  commands: { sendMail: mailer.sendMail },
  initial: "sending",
  states: { sending: {}, done: { type: "final" } },
}).chart({
  states: {
    sending: {
      sends: {
        sendMail: {
          input: () => ({ to: "" }),
          onAccepted: [{ target: "done" }],
          onRejected: [{ target: "done" }],
        },
      },
    },
  },
});

export const tagWatcher = machine({
  description: "Watch each tag, one of which is empty",
  initial: "watching",
  states: { watching: { type: "map", key: { tag: z.string().min(1) }, initial: "idle", states: { idle: {} } } },
}).chart({ states: { watching: { items: () => [{ tag: "home" }, { tag: "" }] } } });

export const taskNamed = query({
  input: { title: Task.fields.title },
  output: { taskId: Task.fields.id.nullable() },
}).resolve(({ input, records }) => ({
  taskId: records.Task.filter((t) => t.title === input.title).only()?.id ?? null,
}));

export const listScreen = screen({
  description: "A list that offers a task with an empty id",
  controls: { pick: { label: "Pick", payload: { taskId: z.string().min(1) } } },
  initial: "listing",
  states: { listing: {} },
}).chart({ offers: { pick: () => [{ taskId: "" }] } });

export const item = query({
  input: { itemId: z.string() },
  output: Item.fields,
}).resolve(({ input, records }) => Reflect.get(records.Item, input.itemId));

export const countAddedTask = automation({
  receives: { taskAdded },
  commands: { countAdded },
}).send({ input: ({ payload }) => ({ title: payload.title }) });

export const titledScreen = screen({
  description: "The tasks whose title starts with a prefix",
  queries: { titled: todo.titled },
  initial: "showing",
  states: { showing: {} },
}).chart({
  states: { showing: { shows: { titled: { input: () => ({ prefix: "" }) } } } },
});

export const archiveTitle = command({
  input: { title: Archive.fields.title },
  emits: [titleArchived],
}).decide(({ input, records }) => [
  records.Task.filter((t) => t.title === input.title).map(() => emit(titleArchived, { title: input.title })),
]);

export const doneScreen = screen({
  description: "A screen that closes with a negative count",
  output: { count: z.number().nonnegative() },
  controls: { close: { label: "Close" } },
  initial: "open",
  states: { open: {}, closed: { type: "final" } },
}).chart({
  offers: { close: any },
  resolve: () => ({ count: -1 }),
  states: { open: { on: { close: [{ target: "closed" }] } } },
});

export const watcher = machine({
  description: "Watch the first task, reading a held value that its state does not have",
  context: { title: z.string().default("") },
  receives: { taskAdded },
  initial: "idle",
  states: { idle: {}, watching: { held: { task: z.object(Task.fields) } } },
}).chart({
  states: {
    idle: { on: { taskAdded: [{ target: "watching", with: { task: ({ records }) => records.Task.only() } }] } },
    watching: {
      entry: { assign: { title: latestTitle } },
      on: { taskAdded: [{ target: "idle" }] },
    },
  },
});

export const addNote = command({
  input: { noteId: z.string() },
  emits: [noteAdded],
}).decide(({ input }) => [emit(noteDrafted, { noteId: input.noteId })]);

export const flow = machine({
  description: "Alternate between two states",
  receives: { taskAdded },
  initial: "a",
  states: { a: {}, b: {} },
}).chart({ states: { a: { always: [{ target: "b" }] }, b: { always: [{ target: "a" }] } } });

export const noticeAdded = automation({
  receives: { added: todo.added },
  commands: { notice },
}).send({});

export const perTask = machine({
  description: "Greet in each copy of a task",
  commands: { greet },
  initial: "rows",
  states: {
    rows: {
      type: "map",
      key: { taskId: ref(Task), rank: z.int().default(0), label: z.object({ text: z.string().default("") }) },
      initial: "greeting",
      states: { greeting: {}, done: {} },
    },
  },
}).chart({
  states: {
    rows: { items: ({ records }) => records.Task.map((t) => ({ taskId: t.id, rank: 1, label: { text: t.id } })) },
    greeting: { sends: { greet: { input: ({ key }) => key, onAccepted: [{ target: "done" }], onRejected: [] } } },
  },
});

export const announce = command({
  input: { taskId: todo.TaskId },
  emits: [todo.taskAdded],
}).decide(({ input }) => [emit(todo.taskAdded, { taskId: input.taskId, title: "" })]);

export const renameTask = command({
  input: { taskId: ref(Task), title: Task.fields.title },
  emits: [taskRenamed],
  binds: { task: ({ input, records }) => records.Task.get(input.taskId) },
  requires: {
    changesTitle: ({ input, bound }) => bound.task.title !== input.title,
    1: ({ input }) => input.title !== "",
  },
}).decide(({ input }) => [emit(taskRenamed, { id: input.taskId, title: input.title })]);

export const reminder = machine({
  description:
    "Remind 2^53 milliseconds after it starts, past every safe integer, and nudge half a millisecond after that",
  initial: "waiting",
  states: { waiting: {}, reminding: {}, done: {} },
}).chart({
  states: {
    waiting: { after: { day: { delay: 2 ** 53, onFired: [{ target: "reminding" }] } } },
    reminding: { after: { nudge: { delay: 0.5, onFired: [{ target: "done" }] } } },
  },
});

export const homeScreen = screen({
  description: "The home screen, which no screen opens, so nothing gives the input that requires would read",
  initial: "showing",
  states: { showing: {} },
  requires: { signedIn: () => false },
}).chart({});

export const reminder = machine({
  description: "Remind an hour before it starts, which no clock reaches",
  initial: "waiting",
  states: { waiting: {}, reminding: {} },
}).chart({
  states: {
    waiting: { after: { early: { delay: -3_600_000, onFired: [{ target: "reminding" }] } } },
  },
});

export const counter = machine({
  description: "Ask for the number of tasks after each added task",
  receives: { taskAdded },
  queries: { taskCount },
  initial: "idle",
  states: { idle: {}, asking: {} },
}).chart({
  states: {
    idle: { on: { taskAdded: [{ target: "asking" }] } },
    asking: { calls: { taskCount: { onFulfilled: [{ target: "idle" }] } } },
  },
});

export const player = machine({
  description: "Play a track, and return to what was playing after a pause",
  receives: { paused },
  initial: "on",
  states: {
    on: {
      initial: "idle",
      states: { idle: {}, playing: { held: { trackId: z.string() } }, back: { type: "history" } },
    },
    pausedNow: {},
  },
}).chart({
  states: {
    idle: { on: { paused: [{ target: "playing", with: { trackId: () => "track-1" } }] } },
    playing: { on: { paused: [{ target: "pausedNow" }] } },
    pausedNow: { on: { paused: [{ target: "back" }] } },
  },
});

export const addTask = command({
  input: { taskId: Task.fields.id, title: Task.fields.title },
  emits: [taskAdded],
}).decide(({ input }) => [emit(taskAdded, { id: input.taskId, title: input.title })]);

export const listScreen = screen({
  description: "A list whose own offers leave out the control close",
  controls: { refresh: { label: "Refresh" }, close: { label: "Close" } },
  initial: "shown",
  states: { shown: {}, closed: { type: "final" } },
}).chart({
  offers: unchecked({ refresh: any }),
  states: { shown: { on: { refresh: [], close: [{ target: "closed" }] } } },
});

export const shelvesListed = event({
  payload: { shelves: sortedBy(z.object({ name: z.string(), rank: z.number().default(0) }), "rank") },
});

export const answerMalformedNextDay = scenario({
  description:
    "Answer the next day with a day that is no whole millisecond; the output schema of nextDay rejects it, so test reports answerOutputSchema",
  given: { start: parseInstant("2026-10-25T09:00:00+09:00"), records: {}, peers: [external(calendar)] },
  when: (w) => {
    w.net.deliver(w.startup.request(calendar.nextDay));
    w.net.deliver(w.peer.calendar.answer(w.startup.request(calendar.nextDay), fulfilled({ day: 1.5 })));
  },
  then: () => [],
});

export const pickTwice = scenario({
  description: "Pick the name a twice; test reports controlPayloadSchema",
  given: { start: parseInstant("2026-10-25T09:00:00+09:00"), records: {}, peers: [external(catalog)] },
  when: (w) => {
    w.user.operate(w.startup.screen(shelfScreen), "pick", { names: ["a", "a"] });
  },
  then: () => [],
});

export const pickUnderDialog = scenario({
  description: "Pick a task while the dialog covers the list; test reports coveredByModal",
  given: arranged,
  when: (w) => {
    const list = w.startup.screen(listScreen);
    w.user.operate(list, "clear");
    w.user.operate(list, "pick", { taskId: "task-1" });
  },
  then: () => [],
});

export const receiveAddedEmptyTitle = scenario({
  description:
    "Receive an added task with an empty title; the payload schema of taskAdded rejects it, so test reports eventPayloadSchema",
  given: arranged,
  when: (w) => {
    w.net.deliver(w.peer.todo.emit(todo.taskAdded, { taskId: "task-1", title: "" }, { resultOf: null }));
  },
  then: () => [],
});

export const answerBeforeFrom = scenario({
  description:
    "Answer a day before from; the answer breaks the assumed ensures afterFrom, so test reports failedAssumedEnsures when the run ends",
  given: { start: parseInstant("2026-10-25T09:00:00+09:00"), records: {}, peers: [external(calendar)] },
  when: (w) => {
    w.net.deliver(w.startup.request(calendar.nextDay));
    w.net.deliver(
      w.peer.calendar.answer(
        w.startup.request(calendar.nextDay),
        fulfilled({ day: parseInstant("2026-10-24T15:00:00Z") }),
      ),
    );
  },
  then: () => [],
});

export const acceptBookingLater = scenario({
  description:
    "Accept a booking an hour after the start of a day; this breaks the assumed requires startOfDay, so test reports failedAssumedRequires and does not check the booked event of another day against the assumed ensures sameDay",
  given: { start: parseInstant("2026-10-25T10:00:00+09:00"), records: {}, peers: [external(calendar)] },
  when: (w) => {
    w.net.deliver(w.startup.request(calendar.book));
    w.net.deliver(w.peer.calendar.answer(w.startup.request(calendar.book), accepted()));
    w.net.deliver(
      w.peer.calendar.emit(
        calendar.booked,
        { day: parseInstant("2026-10-26T00:00:00Z") },
        { resultOf: w.startup.request(calendar.book) },
      ),
    );
  },
  then: () => [],
});

export const rejectBookingAtStartOfDay = scenario({
  description:
    "Reject a booking at the start of a day with requires; startOfDay holds, so test reports rejectedAssumedRequires",
  given: { start: parseInstant("2026-10-25T09:00:00+09:00"), records: {}, peers: [external(calendar)] },
  when: (w) => {
    w.net.deliver(w.startup.request(calendar.book));
    w.net.deliver(w.peer.calendar.answer(w.startup.request(calendar.book), rejected("requires", "startOfDay")));
  },
  then: () => [],
});

export const changedByQuery = scenario({
  description:
    "Link dayChanged to the query nextDay, which the types reject; test reports resultOfNonCommand when the run ends, since only a command's request has result events",
  given: { start: parseInstant("2026-10-25T09:00:00+09:00"), records: {}, peers: [external(calendar)] },
  when: (w) => {
    w.net.deliver(w.startup.request(calendar.nextDay));
    w.net.deliver(
      w.peer.calendar.answer(
        w.startup.request(calendar.nextDay),
        fulfilled({ day: parseInstant("2026-10-25T15:00:00Z") }),
      ),
    );
    w.net.deliver(
      w.peer.calendar.emit(calendar.dayChanged, {}, { resultOf: unchecked(w.startup.request(calendar.nextDay)) }),
    );
  },
  then: () => [],
});

export const grantRejected = scenario({
  description:
    "Link granted to a request that the device rejected; test reports resultOfUnacceptedRequest when the run ends, since the event cannot be that request's result",
  given: { start: parseInstant("2026-10-25T09:00:00+09:00"), records: {}, peers: [external(device)] },
  when: (w) => {
    w.net.deliver(w.startup.request(device.requestPermission));
    w.net.deliver(w.peer.device.answer(w.startup.request(device.requestPermission), rejected("unavailable")));
    w.net.deliver(w.peer.device.emit(device.granted, {}, { resultOf: w.startup.request(device.requestPermission) }));
  },
  then: () => [],
